const perfil = $input.first().json;
const MODALIDADES = { pregao_eletronico: 6, dispensa: 8 };

const hoje = new Date();
const ontem = new Date(hoje.getTime() - 24 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10).replace(/-/g, '');

const modalidades = Array.isArray(perfil.modalidades) ? perfil.modalidades : [];
const out = [];
for (const m of modalidades) {
  const codigo = MODALIDADES[m];
  if (!codigo) continue;
  out.push({ json: {
    perfil_id: perfil.perfil_id,
    nome_perfil: perfil.nome_perfil,
    whatsapp_numero: perfil.whatsapp_numero,
    palavras: perfil.objeto_palavras_chave || [],
    valor_min: perfil.valor_min,
    valor_max: perfil.valor_max,
    uf: perfil.uf || [],
    municipio: perfil.municipio || [],
    modalidade_codigo: codigo,
    dataInicial: fmt(ontem),
    dataFinal: fmt(hoje)
  } });
}
return out;

function normalizar(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const consultas = $('Montar Consultas Modalidade').all();
const respostas = $input.all();
const resultados = [];

for (let i = 0; i < respostas.length; i++) {
  const consulta = consultas[i] ? consultas[i].json : null;
  if (!consulta) continue;
  const registros = (respostas[i].json && respostas[i].json.data) || [];
  const palavrasNorm = (consulta.palavras || []).map(normalizar).filter(Boolean);
  const ufsPerfil = consulta.uf || [];
  const municipiosNorm = (consulta.municipio || []).map(normalizar).filter(Boolean);

  for (const r of registros) {
    const objetoNorm = normalizar(r.objetoCompra);
    const bateuPalavra = palavrasNorm.some(p => objetoNorm.includes(p));
    if (!bateuPalavra) continue;

    const valor = r.valorTotalEstimado != null ? Number(r.valorTotalEstimado) : null;
    if (consulta.valor_min != null && (valor == null || valor < consulta.valor_min)) continue;
    if (consulta.valor_max != null && (valor == null || valor > consulta.valor_max)) continue;

    const uf = r.unidadeOrgao ? r.unidadeOrgao.ufSigla : null;
    if (ufsPerfil.length && !ufsPerfil.includes(uf)) continue;

    const municipio = r.unidadeOrgao ? r.unidadeOrgao.municipioNome : null;
    if (municipiosNorm.length && !municipiosNorm.includes(normalizar(municipio))) continue;

    const cnpj = (r.orgaoEntidade && r.orgaoEntidade.cnpj) || (r.orgaoSubRogado && r.orgaoSubRogado.cnpj) || '';
    const link = 'https://pncp.gov.br/app/editais/' + cnpj + '/' + r.anoCompra + '/' + r.sequencialCompra;

    resultados.push({ json: {
      perfil_id: consulta.perfil_id,
      nome_perfil: consulta.nome_perfil,
      whatsapp_numero: consulta.whatsapp_numero,
      pncp_id: r.numeroControlePNCP,
      objeto: r.objetoCompra,
      orgao: (r.orgaoEntidade && r.orgaoEntidade.razaoSocial) || '',
      valor,
      uf,
      municipio,
      modalidade_nome: r.modalidadeNome,
      link
    } });
  }
}
return resultados;

const candidatos = $('Extrair e Filtrar Editais').all().map(i => i.json);
const jaEnviados = new Set($input.all().map(i => i.json && i.json.pncp_id).filter(Boolean));
return candidatos.filter(c => !jaEnviados.has(c.pncp_id)).map(json => ({ json }));

function formataValor(v) {
  if (v == null) return 'valor nao informado';
  return 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
}
const item = $input.first().json;
const texto = 'Nova licitacao para o alerta "' + item.nome_perfil + '":\n\n' +
  item.objeto.slice(0, 300) + (item.objeto.length > 300 ? '...' : '') + '\n\n' +
  'Orgao: ' + item.orgao + '\n' +
  'Valor estimado: ' + formataValor(item.valor) + '\n' +
  'Modalidade: ' + item.modalidade_nome + '\n' +
  (item.municipio ? ('Local: ' + item.municipio + '/' + item.uf + '\n') : '') +
  '\nEdital: ' + item.link;
return [{ json: { ...item, numero: item.whatsapp_numero.replace(/\D/g, ''), texto } }];
